import{_ as l,l as t,o as a,c as s,v as o,p as i,x as d,d as r,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"ELF 加载","description":"","frontmatter":{"title":"ELF 加载","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exec-loading-elf.md","filePath":"cs/exec-loading-elf.md","lastUpdated":1789023840000}'),_={name:"cs/exec-loading-elf.md"};function E(f,e,h,m,T,u){const c=t("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="elf-加载" tabindex="-1">ELF 加载 <a class="header-anchor" href="#elf-加载" aria-label="Permalink to &quot;ELF 加载&quot;">​</a></h1><div class="epigraph"><p>内核读程序头，按段 `mmap` 进地址空间，设入口；动态则把解释器 `ld.so` 一并映射，由它完成重定位与构造器。</p><footer>—— 据 System V ABI；Linux `fs/binfmt_elf.c` 传统行为；主干[加载与动态链接](/cs/load-dynlink)；Levine 整理</footer></div><p>上一课<a href="/cs/elf-format">ELF 格式</a> 给出表。缺口是<strong>执行</strong>：<code>execve</code> 之后谁映射谁跳。主干加载课有直觉。本课钉内核 vs <code>ld.so</code> 分工、ASLR、辅助向量 <code>auxv</code>。交叉编译下一课收束链接课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>ET_EXEC</code> 固定地址（现代少）；<code>ET_DYN</code> PIE 随机基址。内核：映射 <code>PT_LOAD</code>，处理 <code>PT_INTERP</code>、栈上放 <code>argv</code>/<code>envp</code>/<code>auxv</code>。<code>ld.so</code>：找 <code>.so</code>、写 GOT、跑 <code>DT_INIT</code>。缺口是<strong>这条启动链</strong>，不是节头字段表。</p><p>栈权限、NX、RELRO 在加载时落实。</p><h3 id="加载不是解释字节码" tabindex="-1">加载不是解释字节码 <a class="header-anchor" href="#加载不是解释字节码" aria-label="Permalink to &quot;加载不是解释字节码&quot;">​</a></h3><p>映射后跳到机器入口。字节码 VM 是后一单元。不要把 <code>ld.so</code> 当 JVM。</p><p><span class="marginnote">binfmt_elf。SysV。主干 load-dynlink。本课补内核视角与 auxv（AT_PHDR、AT_ENTRY、AT_RANDOM）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 <code>readelf -l</code> 与 <code>/proc/self/maps</code>。动态：<code>LD_DEBUG=files</code> 看搜索。静态：无 interp，内核跳 <code>e_entry</code>。</p>',11)),(a(),i(p,null,{default:d(()=>[n(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXEC%5B%22execve%22%5D%20--%3E%20KERN%5B%22%E5%86%85%E6%A0%B8%E6%98%A0%E5%B0%84%20PT_LOAD%22%5D%0A%20%20KERN%20--%3E%20INT%7B%22%E6%9C%89%20PT_INTERP%3F%22%7D%0A%20%20INT%20--%3E%7C%E6%98%AF%7C%20LDSO%5B%22ld.so%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20INT%20--%3E%7C%E5%90%A6%7C%20ENT%5B%22%E8%B7%B3%20e_entry%22%5D%0A%20%20LDSO%20--%3E%20ENT%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与<a href="/cs/stack-unwinding">unwind</a>：加载器注册的对象列表供展开器找 FDE。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>失败：找不到 <code>.so</code>、重定位溢出、栈执行被拒。setuid 忽略部分环境（<code>LD_PRELOAD</code>）——安全点名。不要在 setuid 路径依赖预加载。</p><p>构造器顺序：与跨 <code>.so</code> 依赖有关，陷阱。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 <code>mmap</code> 系统课全文。后课默认：ELF 由内核+ld.so 加载。下一课交叉编译与三元组：生成哪一种 ELF。</p><p>也不把加载当浏览器加载 URL。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核映射段并设栈；动态把控制交给 ld.so。</li><li>PIE/ASLR 改基址，重定位必须 PIC。</li><li>auxv 把phdr 与随机数传给用户态。</li><li>出处：ELF/SysV；Linux binfmt_elf；Levine；主干 load-dynlink。</li></ul>',9))])}const L=l(_,[["render",E]]);export{x as __pageData,L as default};
